::deep .thread-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #8e9297;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #36393f;
    color: #fff;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 8px;
    border-radius: 4px;
}

::deep .thread-reply:hover {
    background: #36393f;
}
"}

